import random

def generate_test_case():
    num_nodes = random.randint(0, 2000)
    if num_nodes == 0:
        return []
    tree = [None for _ in range(num_nodes)]
    for _ in range(num_nodes):
        index = random.randint(0, num_nodes-1)
        while tree[index] is not None:
            index = random.randint(0, num_nodes-1)
        tree[index] = random.randint(-100, 100)
    return tree
